node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { runInNewContext } from 'node:vm';
import { build } from 'esbuild';
const sha = x => createHash('sha256').update(x).digest('hex');
const dir = 'docs/remediation/evidence/W02.01/';
const manifest = JSON.parse(readFileSync(dir + 'artifact-manifest-v2.json'));
const files = new Map(manifest.files.map(f => [f.path, f]));
for (const f of files.values()) assert.equal(sha(readFileSync(f.path)), f.sha256, f.path);
const probe = readFileSync(dir + 'reviewer-probe-v2.mjs', 'utf8');
const source = runInNewContext(probe.match(/const source = (String.raw`[\s\S]*?`);\n/)[1]);
const original = readFileSync(dir + 'before-auth.ts.txt', 'utf8').slice(0,-1);
assert.equal(sha(original),'65a1553ae0d93627f82f5c6dd3f5acb8ee3a8b94b7d82955c15098d3c1317492');
const graphs = [];
for (const before of [true,false]) {
 const b = await build({stdin:{contents:source,resolveDir:process.cwd(),sourcefile:'w0201-independent-probe.ts',loader:'ts'},alias:{'@':resolve('src')},bundle:true,write:false,metafile:true,platform:'node',format:'cjs',logLevel:'silent',plugins:before?[{name:'original',setup(b){b.onLoad({filter:/[/\\]src[/\\]middleware[/\\]auth\.ts$/},()=>({contents:original,loader:'ts',resolveDir:resolve('src/middleware')}));}}]:[]});
 const inputs=Object.keys(b.metafile.inputs).sort();
 const physical=inputs.filter(p=>p!=='w0201-independent-probe.ts');
 const uncovered=physical.filter(p=>!files.has(p));
 assert.deepEqual(uncovered,[]);
 assert.ok(inputs.includes('src/auth/signingConfig.mjs'));
 const bundle=sha(b.outputFiles[0].contents);
 assert.equal(bundle,before?'d7c9e9b47ca6fcbad94351d20fc08d9bce3119b6e2b202cb11c20b0601c73f06':'63f9632961705902ed213c453f4f4d5cb593c3005b73d6076c0300d10aeefb24');
 graphs.push({before,inputCount:inputs.length,physicalInputs:physical.length,inputPathsSha256:sha(JSON.stringify(inputs)),bundleSha256:bundle,uncovered});
}
const identities=['artifact-manifest-v2.json','worker-revalidation-v2.md','worker-k1-v2.log','reviewer-probe-v2.mjs'].map(p=>({path:dir+p,sha256:sha(readFileSync(dir+p))}));
console.log(JSON.stringify({at:new Date().toISOString(),result:'pass',files:files.size,digest:manifest.digest,graphs,identities},null,2));
NODE
